// === UREDI VRIJEDNOSTI OVDJE ===
const cfg = {
  ACTION: 'backfill',              // count | backfill | enrich
  ACCOUNT_EMAIL: 'mario.vitt@oriphiel.hr',
  ENV_FILE: 'accounts/oriphiel.hr-mario.vitt.env',
  STATUS_TAG: 'mario.vitt',
  RUN_AI: '0',                     // 0=ne | 1=da (backfill)
  RESET_BEFORE: '0',               // 0=ne | 1=da (briše mailove!)
  BATCH_SIZE: '50',
  MARK_AS_SEEN: '0',               // 0=ne | 1=da
};

function clean(v) {
  if (v == null) return '';
  if (typeof v === 'object' && v.value != null) return String(v.value).trim();
  return String(v).trim();
}

const out = {};
for (const [k, v] of Object.entries(cfg)) {
  out[k] = clean(v);
}
out.ACTION = (out.ACTION || 'count').toLowerCase();

if (!out.ACCOUNT_EMAIL) {
  throw new Error('ACCOUNT_EMAIL je prazan u Account Config');
}
if (out.ACTION === 'backfill' && !out.ENV_FILE) {
  throw new Error('ENV_FILE je prazan u Account Config');
}

return [{ json: out }];

const c = $('Account Config').first().json;
const email = String(c.ACCOUNT_EMAIL || '').trim();
const envFile = String(c.ENV_FILE || '').trim();
if (!email || !envFile) throw new Error('ACCOUNT_EMAIL ili ENV_FILE prazan');

const sh = (s) => `'${String(s).replace(/'/g, "'\\''")}'`;
const tag = String(c.STATUS_TAG || 'account').replace(/[^a-zA-Z0-9._-]/g, '') || 'account';
const status = `/tmp/oriphiel-imap-backfill-${tag}.json`;

// ^python3 — da pgrep ne pogodi sam bash -c (koji sadrži ime skripte)
const guard = "if pgrep -f '^python3 -u .*sync-imap-backfill\\.py' >/dev/null; then echo ALREADY_RUNNING; cat " + sh(status) + " 2>/dev/null; exit 0; fi";

const start = '(nohup env ENV_FILE=' + sh(envFile) + ' ACCOUNT_EMAIL=' + sh(email) + ' RESET_BEFORE=' + (c.RESET_BEFORE || '0') + ' RUN_AI=' + (c.RUN_AI || '0') + ' BATCH_SIZE=' + (c.BATCH_SIZE || '50') + ' MARK_AS_SEEN=' + (c.MARK_AS_SEEN || '0') + ' STATUS_FILE=' + sh(status) + ' bash sync-imap-backfill.sh >>/tmp/oriphiel-imap-backfill-last.log 2>&1 & echo STARTED_PID=$!)';

const command = [
  'cd /root/oriphiel-ai/oriphiel_messaging',
  guard,
  start,
  'sleep 2',
  'cat ' + sh(status) + ' 2>/dev/null || echo status_pending'
].join(' && ');

return [{ json: { ...c, command, status_file: status } }];

const c = $('Account Config').first().json;
const email = String(c.ACCOUNT_EMAIL || '').trim();
if (!email) throw new Error('ACCOUNT_EMAIL prazan');

const sh = (s) => `'${String(s).replace(/'/g, "'\\''")}'`;
const tag = String(c.STATUS_TAG || 'account').replace(/[^a-zA-Z0-9._-]/g, '') || 'account';
const status = `/tmp/oriphiel-ai-enrich-${tag}.json`;

const guard = "if pgrep -f '^python3 -u .*enrich-existing-messages\\.py' >/dev/null; then echo ALREADY_RUNNING; cat " + sh(status) + " 2>/dev/null; exit 0; fi";

const start = '(nohup env ACCOUNT_EMAIL=' + sh(email) + ' ONLY_MISSING=1 LIMIT=0 BATCH_SIZE=10 OLLAMA_MODEL=llama3.1:8b STATUS_FILE=' + sh(status) + ' python3 -u enrich-existing-messages.py >>/tmp/oriphiel-ai-enrich-last.log 2>&1 & echo STARTED_PID=$!)';

const command = [
  'cd /root/oriphiel-ai/oriphiel_messaging',
  guard,
  'if [ ! -f ollama-enrich-message.py ] || [ ! -f enrich-existing-messages.py ]; then echo MISSING_FILES; exit 2; fi',
  start,
  'sleep 2',
  'cat ' + sh(status) + ' 2>/dev/null || echo status_pending'
].join(' && ');

return [{ json: { ...c, command, status_file: status } }];
